-- A small slice of content/ for tests, captured when the service was seeded.
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('alexander-block', 'maintainer', 'Being a guest on David''s Rawkode Academy channel was a very great experience. This was my first time being a guest in such a format and David made sure that it turned out being a great session. My project was very well represented, especially due to David actively following and being able to ask the interesting and challenging questions. If you have an interesting project to show and feel that people would benefit, don''t hesitate to get in contact with David.
', 'Alexander Block', 'Maintainer of Kluctl', 'https://avatars.githubusercontent.com/u/1884269?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('avinash-upadhyaya', 'viewer', 'Rawkode Academy is the perfect place for mid to senior level engineers looking for content in the Cloud Native space. The videos act as a perfect guide for anyone looking to go beyond basics and becoming an expert in the field. The Klustered series is a must watch for anyone involved in operating Kubernetes clusters. The channel often has other industry experts joining and sharing their knowledge as well apart from Rawkode. I would definitely recommend and have recommended the channel in the past for anyone looking to skill up in the Cloud Native ecosystem.
', 'Avinash Upadhyaya K R', 'Platform & DevOps Engineer at Platformatory', 'https://avinashupadhya99.github.io/images/profile.png', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('brain-ketelsen', 'maintainer', 'David is the consummate host and made me feel welcome and comfortable on his show. His knowledge of the tech ecosystem is unparalleled and I highly encourage others to join him if given the opportunity!
', 'Brian J Ketelsen', 'Go Expert', 'https://avatars.githubusercontent.com/u/37492?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('gianluca-arbezzano', 'viewer', 'Rawkode Academy is my go to channel to stay up to date with projects I realy on on my day to day job. It is cool to know that there is a content creator that brings to gether industry leaders but also maintainers to give them a friendly place where they can share what they are up to.
I also worked with David for many years but unfortunaty I still need to win a single  pool match against him!
', 'Gianluca Arbezzano', 'Developer', 'https://avatars.githubusercontent.com/u/1630267', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('hugo-santos', 'maintainer', 'I felt super welcomed by David in his show. I got enough guidance ahead of time, and appreciated the way that the show went as a back and forth between him and myself. David is an expert and it shows. But he approaches the questions in a thoughtful manner that help bridge the gap between the presenter and the audience.

I''d be happy to be back at the show, and would encourage others to join as well.
', 'Hugo Santos', 'CEO of Namespace Labs', 'https://avatars.githubusercontent.com/u/175449?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('jens-neuse', 'maintainer', 'It was amazing working together with David. It''s hard to present a deep tech product, but David is so knowledgeable about the web and everything so we were  having a great conversation and lots of fun. Additionally, I have to compliment David on how fluent he is in exploring a new project and doing live coding. It was great to see him explore WunderGraph for the first time, especially to see the excitement when we were combining APIs, first with GraphQL and then with TypeScript. I think this was an amazing presentation and I would recommend everyone to go on this show and present their work. David is amazing. I''m super thankful for this opportunity.
', 'Jens Neuse', 'CEO & Co-Founder of WunderGraph', 'https://media.licdn.com/dms/image/v2/D4E03AQGJJtkdHlQ-ig/profile-displayphoto-shrink_400_400/B4EZU.oFfAHcAg-/0/1740512451230?e=1748476800&v=beta&t=VGeORJsofZdYdAjANVd6-ewpnYJ9L25DQP8_5r1DAt4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('joshua-jebaraj', 'viewer', 'Rawkode Academy is one of the best youtube channel out there, the amount of stuff I learned from the klustered is insane. Being not a big fan of traditional method of learning stuffs, Klustered helps me to learn a lot of stuffs by breaking and fixing stuffs. If someone wants to learn and level up the kubernetes skills beyond the basics, I would highly recommend to checking out Rawkode Academy.
', 'Joshua Jebaraj', 'Security Researcher', 'https://avatars.githubusercontent.com/u/19353065?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('marcos-nils', 'maintainer', 'Had a blast joining David on this klustered series not once, but twice. Best channel in the Cloud Native space which targets both an experienced and entry-level audience.

Looking forward to coming back soon!
', 'Marcos Nils', 'Kubernetes Expert & Dagger Maintainer', 'https://avatars.githubusercontent.com/u/1578458?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('mikkel-hegnhoj', 'partner', 'Rawkode Academy has done an amazing job helping developers be introduced to the world of server-side WebAssembly, promoting Spin project and Fermyon Cloud. We''ve heard from many developers, that the Advent of Spin challenges, created by Rawkode, was the perfect opportunity to get hands-on, and we''ve seen notable results in developers joining our community and using our services.
', 'Mikkel Mørk Hegnhøj', 'Head of DevRel at Fermyon', 'https://www.fermyon.com/static/image/profile/mikkel-hegnhoj.jpg', 'https://fermyon.com', 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('reggie-wilkerson', 'partner', 'Working with David and Rawkode Academy has been incredibly valuable for our early-stage journey at Guidepad. His deep expertise in the cloud native landscape has helped us refine our product positioning, create compelling demo videos, and confidently navigate the market. The guidance and insights we receive from David consistently elevate our product and strategy, making this partnership truly invaluable. We look forward to continuing this partnership as we evolve and grow in the market.
', 'Reggie Wilkerson', 'Co-Founder & CEO at Guidepad', 'https://media.licdn.com/dms/image/v2/C4E03AQFOPPjnnDM3sQ/profile-displayphoto-shrink_800_800/profile-displayphoto-shrink_800_800/0/1667932645366?e=1747872000&v=beta&t=fLl3GgbVrGLilgNi6_uut8XYQp-8YU28VRq5P0D3iOU', 'https://guidepad.io', 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('solomon-hykes', 'maintainer', 'Being a guest on Rawkode is always a fun experience. As a builder, watching someone use your product in real time is one of the most useful things you can do. If they''re experienced enough to give you useful feedback as they do it, even better. Doing it all in front of a live audience... let''s just say you''ll be extra productive the day before 😁. Your community will appreciate the transparency and authenticity of an unscripted interaction.

I encourage every builder to join Rawkode Academy if you have the chance. It will make you, and your product, better.
', 'Solomon Hykes', 'Co-Founder of Docker & Dagger', 'https://avatars.githubusercontent.com/u/29565?v=4', NULL, 1764608082000)
--> statement-breakpoint
INSERT INTO `testimonials` (`id`, `type`, `quote`, `author_name`, `author_title`, `author_image`, `author_link`, `updated_at`) VALUES ('stefan-ruzitschka', 'viewer', 'Watching David''s videos helped me learning about several useful tools in the cloud native landscape.
I think that Rawkode Academy is a great and inclusive place where the only thing that matters is the will to learn.
I''m also happy to help the Rawkode Academy become an even more awesome place for learning, thanks for having me!
', 'Stefan Ruzitschka', 'DevOps Engineer', 'https://avatars.githubusercontent.com/u/362487?v=4', NULL, 1764608082000)
